css:
& { align-content: center; gap: 36px; }
.eyebrow { color: var(--accent); font-size: 32px; font-weight: 600; margin: 0; }
.nums { list-style: none; margin: 16px 0 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fit, minmax(0, 1fr)); grid-auto-flow: column; gap: 48px; counter-reset: n; }
.nums li { counter-increment: n; border-top: 3px solid var(--accent); padding-top: 24px; display: grid; gap: 12px; align-content: start; }
.nums li::before { content: counter(n, decimal-leading-zero); font-family: var(--font-display); font-size: 100px; font-weight: 700; line-height: 1; color: var(--accent); }
.nums b { font-size: 40px; }
.nums span { font-size: 30px; line-height: 1.35; color: var(--muted); }
